**Files:** `mobile/supabase/functions/_shared/prompts.ts`

`buildSystemPrompt`, `buildForcedReference`, `getPersonalityVoice`, `buildMorningBriefPrompt` — not a single test. These are the entire personality system.

```typescript
// tests/unit/prompts.test.ts
import { getPersonalityVoice, buildSystemPrompt, buildForcedReference } from '../mobile/supabase/functions/_shared/prompts';

const baseCtx = {
  userName: 'Jensen',
  streak: 5,
  dopamineScore: 70,
  doneHabits: ['Workout'],
  missedHabits: [],
  identityStatement: 'gets things done',
  goals: [],
  monkMode: false,
  strictGoals: false,
};

describe('getPersonalityVoice', () => {
  test('returns stoic_mentor as default for unknown personality', () => {
    const voice = getPersonalityVoice('unknown_coach');
    expect(voice).toContain('Stoic');
  });

  test.each(['drill_sergeant','stoic_mentor','anime_sensei','goggins','ceo_coach','calm_therapist'])(
    '%s returns non-empty voice string',
    (personality) => {
      expect(getPersonalityVoice(personality).length).toBeGreaterThan(20);
    }
  );

  test('drill_sergeant voice contains military directness markers', () => {
    const voice = getPersonalityVoice('drill_sergeant');
    expect(voice).toMatch(/military|drill|aggressive/i);
  });
});

describe('buildSystemPrompt', () => {
  test('prompt contains user name', () => {
    const prompt = buildSystemPrompt('stoic_mentor', baseCtx);
    expect(prompt).toContain('Jensen');
  });

  test('prompt contains streak value', () => {
    const prompt = buildSystemPrompt('stoic_mentor', baseCtx);
    expect(prompt).toContain('5');
  });

  test('MONK MODE appended when monkMode=true', () => {
    const prompt = buildSystemPrompt('stoic_mentor', { ...baseCtx, monkMode: true });
    expect(prompt).toContain('MONK MODE ACTIVE');
    expect(prompt).toContain('50 words max');
  });

  test('STRICT GOALS appended when strictGoals=true', () => {
    const prompt = buildSystemPrompt('stoic_mentor', { ...baseCtx, strictGoals: true });
    expect(prompt).toContain('STRICT GOALS MODE');
  });

  test('coachMemory block included when present', () => {
    const prompt = buildSystemPrompt('stoic_mentor', { ...baseCtx, coachMemory: 'User skips Sundays' });
    expect(prompt).toContain('User skips Sundays');
    expect(prompt).toContain('COACH MEMORY');
  });

  test('no coachMemory block when coachMemory is empty', () => {
    const prompt = buildSystemPrompt('stoic_mentor', { ...baseCtx, coachMemory: '' });
    expect(prompt).not.toContain('COACH MEMORY');
  });
});

describe('buildForcedReference — missed habits', () => {
  test('requires naming missed habits by name', () => {
    const prompt = buildSystemPrompt('stoic_mentor', {
      ...baseCtx,
      missedHabits: ['Meditation', 'Cold shower'],
    });
    expect(prompt).toContain('Meditation');
    expect(prompt).toContain('Cold shower');
  });

  test('stalled goal (progress<30, daysSince>14) forces reference', () => {
    const prompt = buildSystemPrompt('stoic_mentor', {
      ...baseCtx,
      goals: [{ name: 'Write book', progress: 15, daysSince: 20 }],
    });
    expect(prompt).toContain('Write book');
    expect(prompt).toContain('stalled');
  });

  test('streak reference used when no other forced refs', () => {
    const prompt = buildSystemPrompt('stoic_mentor', baseCtx);
    expect(prompt).toContain('5-day streak');
  });

  test('eveningFailed reason gets forced reference', () => {
    const prompt = buildSystemPrompt('stoic_mentor', {
      ...baseCtx,
      eveningFailed: true,
      eveningReason: 'Got distracted by Netflix',
    });
    expect(prompt).toContain('Got distracted by Netflix');
  });

  test('identityStatement included in forced refs', () => {
    const prompt = buildSystemPrompt('stoic_mentor', {
      ...baseCtx,
      identityStatement: 'finishes what they start',
    });
    expect(prompt).toContain('finishes what they start');
  });
});
