**File:** `mobile/supabase/functions/_shared/limits.ts`

Complex optimistic-lock concurrency logic (the `eq('daily_messages', user.daily_messages)` guard) — zero tests.

```typescript
// tests/unit/limits.test.ts
// Requires mocking Supabase createClient

describe('checkMessageLimit', () => {
  test('pro user always passes (returns null)', async () => {
    mockUser({ is_pro: true, daily_messages: 9999, messages_reset_date: today() });
    const result = await checkMessageLimit('user-1', corsHeaders);
    expect(result).toBeNull();
  });

  test('free user at limit returns 200 with limitReached:true', async () => {
    mockUser({ is_pro: false, daily_messages: 10, messages_reset_date: today() });
    const res = await checkMessageLimit('user-1', corsHeaders);
    const body = await res!.json();
    expect(body.limitReached).toBe(true);
    expect(body.limit).toBe(10);
  });

  test('free user under limit increments counter and returns null', async () => {
    mockUser({ is_pro: false, daily_messages: 5, messages_reset_date: today() });
    const result = await checkMessageLimit('user-1', corsHeaders);
    expect(result).toBeNull();
    expect(mockUpdateCalls()).toContainEqual({ daily_messages: 6 });
  });

  test('new day resets counter to 1 regardless of previous value', async () => {
    mockUser({ is_pro: false, daily_messages: 10, messages_reset_date: '2025-01-01' });
    const result = await checkMessageLimit('user-1', corsHeaders);
    expect(result).toBeNull();
    expect(mockUpdateCalls()).toContainEqual({ daily_messages: 1, messages_reset_date: today() });
  });

  test('race condition: re-reads and blocks if fresh count at limit', async () => {
    // First update returns count=0 (optimistic lock failed — raced)
    mockUpdateReturnsCount(0);
    mockUser({ is_pro: false, daily_messages: 5, messages_reset_date: today() });
    mockFreshRead({ daily_messages: 10 }); // someone else incremented to limit
    const res = await checkMessageLimit('user-1', corsHeaders);
    const body = await res!.json();
    expect(body.limitReached).toBe(true);
  });

  test('unknown user returns limitReached', async () => {
    mockUser(null);
    const res = await checkMessageLimit('nonexistent', corsHeaders);
    const body = await res!.json();
    expect(body.limitReached).toBe(true);
  });
});

describe('checkProOnly', () => {
  test('pro user returns null', async () => {
    mockUser({ is_pro: true });
    expect(await checkProOnly('user-1', corsHeaders)).toBeNull();
  });

  test('free user returns 200 with pro_required', async () => {
    mockUser({ is_pro: false });
    const res = await checkProOnly('user-1', corsHeaders);
    const body = await res!.json();
    expect(body.limitReached).toBe(true);
    expect(body.reason).toBe('pro_required');
  });
});
