**File:** `mobile/src/services/offline.ts`

The dedup logic (last toggle wins for same `habitId+date`) and `drainOfflineQueue` concurrency guard are untested.

```typescript
// tests/unit/offline.test.ts
import { enqueueAction, getQueue, removeAction, clearQueue } from '../../mobile/src/services/offline';

beforeEach(() => clearQueue());

describe('enqueueAction — deduplication', () => {
  test('queues a new action', async () => {
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-25' } });
    const q = await getQueue();
    expect(q).toHaveLength(1);
  });

  test('same habitId+date overwrites previous entry (last toggle wins)', async () => {
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-25' } });
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: false, date: '2025-05-25' } });
    const q = await getQueue();
    expect(q).toHaveLength(1);
    expect(q[0].payload.completed).toBe(false); // last write wins
  });

  test('different date on same habitId creates separate entries', async () => {
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-24' } });
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-25' } });
    expect(await getQueue()).toHaveLength(2);
  });

  test('different habitId on same date creates separate entries', async () => {
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-25' } });
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h2', completed: true, date: '2025-05-25' } });
    expect(await getQueue()).toHaveLength(2);
  });
});

describe('removeAction', () => {
  test('removes action by id, leaves others', async () => {
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-25' } });
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h2', completed: true, date: '2025-05-25' } });
    const q = await getQueue();
    await removeAction(q[0].id);
    expect(await getQueue()).toHaveLength(1);
    expect((await getQueue())[0].payload.habitId).toBe('h2');
  });

  test('removeAction on nonexistent id is a no-op', async () => {
    await enqueueAction({ type: 'habit_toggle', payload: { habitId: 'h1', completed: true, date: '2025-05-25' } });
    await removeAction('does-not-exist');
    expect(await getQueue()).toHaveLength(1);
  });
});

describe('drainOfflineQueue', () => {
  test('returns 0 when queue is empty', async () => {
    const { drainOfflineQueue } = await import('../../mobile/src/services/syncQueue');
    expect(await drainOfflineQueue()).toBe(0);
  });

  test('concurrent drain calls are no-ops (draining guard)', async () => {
    // Simulate two simultaneous calls — second should return 0
    const { drainOfflineQueue } = await import('../../mobile/src/services/syncQueue');
    const [r1, r2] = await Promise.all([drainOfflineQueue(), drainOfflineQueue()]);
    expect(Math.min(r1, r2)).toBe(0); // one of them was blocked
  });
});
