// tests/unit/milestones.test.ts
describe('checkAndAwardMilestones', () => {
  test('awards first_habit on first completion', async () => {
    mockDB({ streak: 0, dopamine_score: 50, milestones_earned: [], totalCompletions: 1 });
    const m = await checkAndAwardMilestones('user-1');
    expect(m?.id).toBe('first_habit');
  });

  test('does not re-award already-earned milestone', async () => {
    mockDB({ streak: 7, dopamine_score: 50, milestones_earned: ['streak_7'], totalCompletions: 10 });
    const m = await checkAndAwardMilestones('user-1');
    expect(m?.id).not.toBe('streak_7');
  });

  test('awards streak_100 at exactly 100 days', async () => {
    mockDB({ streak: 100, dopamine_score: 50, milestones_earned: ['first_habit','streak_7','streak_30'], totalCompletions: 200 });
    const m = await checkAndAwardMilestones('user-1');
    expect(m?.id).toBe('streak_100');
  });

  test('awards score_100 at perfect dopamine score', async () => {
    mockDB({ streak: 0, dopamine_score: 100, milestones_earned: ['score_80'], totalCompletions: 0 });
    const m = await checkAndAwardMilestones('user-1');
    expect(m?.id).toBe('score_100');
  });

  test('perfect_day requires at least 1 habit (not triggered with 0 habits)', async () => {
    mockDB({ streak: 0, dopamine_score: 50, milestones_earned: [], totalCompletions: 0, habitCount: 0 });
    const m = await checkAndAwardMilestones('user-1');
    // perfect_day should NOT be awarded when there are no habits
    expect(m?.id).not.toBe('perfect_day');
  });

  test('perfect_day awarded when all habits done', async () => {
    mockDB({ streak: 0, dopamine_score: 50, milestones_earned: ['first_habit'], totalCompletions: 3, habitCount: 3, doneToday: 3 });
    const m = await checkAndAwardMilestones('user-1');
    expect(m?.id).toBe('perfect_day');
  });

  test('returns null when no user found', async () => {
    mockDB(null);
    const m = await checkAndAwardMilestones('ghost-user');
    expect(m).toBeNull();
  });
});

describe('checkGoalMilestone', () => {
  test('awards goal_complete when a goal reaches 100%', async () => {
    mockDB({ milestones_earned: [], goalsAt100: 1 });
    const m = await checkGoalMilestone('user-1');
    expect(m?.id).toBe('goal_complete');
  });

  test('does not re-award goal_complete', async () => {
    mockDB({ milestones_earned: ['goal_complete'], goalsAt100: 5 });
    const m = await checkGoalMilestone('user-1');
    expect(m).toBeNull();
  });
});
