  await expect(heroCta).toBeVisible();
  await heroCta.click();
  // Should navigate somewhere (not stay on same page or throw)
  await page.waitForTimeout(500);
  const url = page.url();
  expect(url).not.toBe('about:blank');
});

test('renders correctly on mobile viewport', async ({ page, browser }) => {
  const mobilePage = await browser.newPage();
  await mobilePage.setViewportSize({ width: 390, height: 844 });
  await mobilePage.goto('/monk-landing.html');

  // Nav should still be visible (or hamburger menu)
  await expect(mobilePage.locator('#nav')).toBeVisible();
  // h1 should be readable
  await expect(mobilePage.locator('h1').first()).toBeVisible();
  await mobilePage.close();
});

test('OG meta tags present', async ({ page }) => {
  const og = {
    'og:title': await page.$eval('meta[property="og:title"]', el => el.getAttribute('content')).catch(() => null),
