// tests/unit/context.test.ts
describe('buildCoachContext', () => {
  test('doneHabits and missedHabits partition correctly', async () => {
    // Mock: 3 habits, 2 completed today
    mockHabits(['h1','h2','h3']);
    mockCompletions(['h1','h3']);
    const ctx = await buildCoachContext('user-1');
    expect(ctx.doneHabits).toHaveLength(2);
    expect(ctx.missedHabits).toHaveLength(1);
  });

  test('eveningFailed is undefined when no evening check-in exists', async () => {
    mockCheckins([]);
    const ctx = await buildCoachContext('user-1');
    expect(ctx.eveningFailed).toBeUndefined();
  });

  test('eveningFailed is false when evening.completed is true', async () => {
    mockCheckins([{ type: 'evening', completed: true, reason: null }]);
    const ctx = await buildCoachContext('user-1');
    expect(ctx.eveningFailed).toBe(false);
  });

  test('daysSince calculated correctly for goals', async () => {
    const created = new Date(Date.now() - 10 * 86400000).toISOString();
    mockGoals([{ name: 'Ship app', progress: 40, created_at: created }]);
    const ctx = await buildCoachContext('user-1');
    expect(ctx.goals[0].daysSince).toBeCloseTo(10, 0);
  });

  test('falls back to Monk defaults when user row is null', async () => {
    mockUserRow(null);
    const ctx = await buildCoachContext('user-1');
    expect(ctx.userName).toBe('Monk');
    expect(ctx.streak).toBe(0);
    expect(ctx.dopamineScore).toBe(50);
  });
});
